/**
 * Build-time loader of the financial-model pages (財報模型): the memory topic sub-pages (/memory/phison/,
 * /memory/micron/) and the /forecast/ topic (/forecast/<id>/). Which companies exist, where their files live and the
 * per-company wording come from src/lib/forecast-config.ts (FC_META).
 *
 * Files: src/data/memory/forecast/market-prices.yaml (shared memory-price inputs, loaded for every company) and, per
 * company, <id>-inputs.yaml (sourced company inputs), <id>-model.json (generated by scripts/models/<id>.ts) and,
 * for the /forecast/ companies, the optional <id>-drivers.yaml (company-specific driver series) — in
 * src/data/memory/forecast/ (topic 'memory') or src/data/forecast/ (topic 'forecast'). Every file is validated with
 * the zod schemas of src/schemas/forecast.ts. A missing inputs or model file hides that company's page (and the links
 * to it); an invalid file fails the build with the schema issues (run npx tsx scripts/check-forecast.ts for details).
 *
 * Besides loading, this module owns the page conventions shared by the components in
 * src/components/memory/forecast/ and src/components/forecast/: period labels (calendar quarters, fiscal quarters
 * with FC_META.fyStartMonth), number formatting (億元／億美元, %, EPS), the citation parsing of model text (raw source
 * keys → [n] markers) and pageSourceKeys(), the list of sources a page cites (registered before rendering so every
 * [n] matches the list).
 */
import { existsSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { parse } from 'yaml';
import {
  companyDrivers,
  companyInputs,
  marketPrices,
  modelOutput,
  type CompanyDrivers,
  type CompanyInputs,
  type MarketPrices,
  type ModelOutput,
} from '../schemas/forecast';
import type { SourceT } from '../schemas/common';
import { formatMoney, formatNumber, joinZh, moneyUnitLabel, scaleMillions } from './format';
import { withBase } from './paths';
import { FC_META, fcCompaniesOf, type FcCompany, type FcMeta, type FcTopic } from './forecast-config';

// ───────────── companies ─────────────

export { FC_META, fcCompaniesOf };
export type { FcCompany, FcMeta, FcTopic };
/** Every company with a config entry, in chain order (pages exist only where hasForecast() is true). */
export const FC_COMPANIES: readonly FcCompany[] = fcCompaniesOf();

/** Site path of a model page: '/memory/phison/', '/forecast/tsmc/' (FC_META[c].path). */
export const forecastPath = (c: FcCompany): string => FC_META[c].path;
export const forecastHref = (c: FcCompany): string => withBase(forecastPath(c));

// ───────────── loading ─────────────

export interface FcBundle {
  company: FcCompany;
  meta: FcMeta;
  inputs: CompanyInputs;
  model: ModelOutput;
  prices: MarketPrices;
  /** company-specific driver series (<id>-drivers.yaml; /forecast/ companies only, optional) */
  drivers: CompanyDrivers | undefined;
  /** every source of the inputs, drivers and price files, keyed (key = the file's local key) */
  sourceByKey: Map<string, SourceT>;
}

const PRICES = 'src/data/memory/forecast/market-prices.yaml';
/** Folder of a company's files (relative to the project root). */
export const forecastDir = (c: FcCompany): string => (FC_META[c].topic === 'memory' ? 'src/data/memory/forecast' : 'src/data/forecast');
const abs = (rel: string) => join(process.cwd(), rel);
const inputsFile = (c: FcCompany) => `${forecastDir(c)}/${c}-inputs.yaml`;
const modelFile = (c: FcCompany) => `${forecastDir(c)}/${c}-model.json`;
const driversFile = (c: FcCompany) => `${forecastDir(c)}/${c}-drivers.yaml`;
/** files a page needs (all must exist) */
const requiredFor = (c: FcCompany) => [PRICES, inputsFile(c), modelFile(c)];

const cache = new Map<FcCompany, { stamp: string; data: FcBundle }>();

function stampOf(c: FcCompany): string {
  return [...requiredFor(c), driversFile(c)]
    .map((f) => {
      try {
        return `${f}:${statSync(abs(f)).mtimeMs}`;
      } catch {
        return `${f}:-`;
      }
    })
    .join('|');
}

/** True when the price, inputs and model files of a company exist (the page and the links to it are built only then). */
export function hasForecast(c: FcCompany): boolean {
  return c in FC_META && requiredFor(c).every((f) => existsSync(abs(f)));
}

/** Companies of a topic (all when omitted) that have a page, in chain order. */
export const forecastCompaniesWithPages = (topic?: FcTopic): FcCompany[] => fcCompaniesOf(topic).filter((c) => hasForecast(c));

function load<T>(f: string, schema: { safeParse: (v: unknown) => { success: true; data: T } | { success: false; error: { issues: Array<{ path: PropertyKey[]; message: string }> } } }): T {
  const txt = readFileSync(abs(f), 'utf8');
  let raw: unknown;
  try {
    raw = f.endsWith('.json') ? JSON.parse(txt) : parse(txt);
  } catch (e) {
    throw new Error(`[forecast-data] ${f}: parse error: ${(e as Error).message}`);
  }
  const r = schema.safeParse(raw);
  if (!r.success) {
    const issues = r.error.issues.slice(0, 5).map((i) => `${i.path.map(String).join('.')}: ${i.message}`);
    throw new Error(`[forecast-data] ${f} does not match src/schemas/forecast.ts — ${issues.join('; ')} (run npx tsx scripts/check-forecast.ts)`);
  }
  return r.data;
}

export function getForecastData(c: FcCompany): FcBundle | undefined {
  if (!hasForecast(c)) {
    console.warn(`[forecast-data] ${c}: missing files in ${forecastDir(c)}; the ${FC_META[c]?.path ?? c} page is skipped`);
    return undefined;
  }
  const stamp = stampOf(c);
  const hit = cache.get(c);
  if (hit && hit.stamp === stamp) return hit.data;
  const prices = load<MarketPrices>(PRICES, marketPrices);
  const inputs = load<CompanyInputs>(inputsFile(c), companyInputs);
  const model = load<ModelOutput>(modelFile(c), modelOutput);
  const drivers = existsSync(abs(driversFile(c))) ? load<CompanyDrivers>(driversFile(c), companyDrivers) : undefined;
  if (inputs.company !== c || model.company !== c || (drivers && drivers.company !== c))
    throw new Error(`[forecast-data] ${c}: company mismatch in the inputs, drivers or model file`);
  const sourceByKey = new Map<string, SourceT>();
  const all = [...Object.entries(inputs.sources), ...Object.entries(drivers?.sources ?? {}), ...Object.entries(prices.sources)];
  for (const [k, s] of all) {
    const had = sourceByKey.get(k);
    // the drivers file repeats many keys of the inputs file (same report): only a different URL is a conflict
    if (had) {
      if (had.url !== s.url) console.warn(`[forecast-data] ${c}: source key "${k}" is defined twice with different URLs; the first one is used`);
    } else sourceByKey.set(k, { ...s, key: k });
  }
  const data: FcBundle = { company: c, meta: FC_META[c], inputs, model, prices, drivers, sourceByKey };
  cache.set(c, { stamp, data });
  return data;
}

// ───────────── periods ─────────────

const RE_Q = /^(FY)?(\d{4})Q([1-4])$/;
const RE_Y = /^(FY)?(\d{4})$/;
const ZH_Q = ['', '一', '二', '三', '四'];

export const isQuarter = (p: string): boolean => RE_Q.test(p);
export const isYear = (p: string): boolean => RE_Y.test(p);

/** Sortable index of a quarter (FY and calendar quarters share the scale): 2026Q3 → 8106. */
export function qIndex(p: string): number {
  const m = RE_Q.exec(p);
  return m ? Number(m[2]) * 4 + Number(m[3]) - 1 : Number.NaN;
}

export function comparePeriods(a: string, b: string): number {
  const ka = isQuarter(a) ? qIndex(a) : Number(RE_Y.exec(a)?.[2] ?? 0) * 4 + 3.5;
  const kb = isQuarter(b) ? qIndex(b) : Number(RE_Y.exec(b)?.[2] ?? 0) * 4 + 3.5;
  return ka - kb;
}

/** Next quarter id in the same style: 2026Q4 → 2027Q1, FY2027Q4 → FY2028Q1. */
export function nextQuarter(p: string): string {
  const m = RE_Q.exec(p);
  if (!m) return p;
  const y = Number(m[2]);
  const q = Number(m[3]);
  return q === 4 ? `${m[1] ?? ''}${y + 1}Q1` : `${m[1] ?? ''}${y}Q${q + 1}`;
}

/**
 * Display labels. short: 「2026 Q3」「FY2027 Q1」「2027 年」「FY2027」; long: 「2026 年第三季」「FY2027 第一季」「2027 全年」「FY2027 全年」.
 */
export function periodLabel(p: string, style: 'short' | 'long' = 'short'): string {
  const q = RE_Q.exec(p);
  if (q) {
    const fy = !!q[1];
    if (style === 'long') return fy ? `FY${q[2]} 第${ZH_Q[Number(q[3])]}季` : `${q[2]} 年第${ZH_Q[Number(q[3])]}季`;
    return fy ? `FY${q[2]} Q${q[3]}` : `${q[2]} Q${q[3]}`;
  }
  const y = RE_Y.exec(p);
  if (y) return y[1] ? `FY${y[2]}${style === 'long' ? ' 全年' : ''}` : `${y[2]} ${style === 'long' ? '全年' : '年'}`;
  return p;
}

/**
 * Calendar months of a period: 2026Q3 → 「2026 年 7–9 月」; fiscal quarters follow the month the fiscal year starts in
 * (`fyStart`, default 9 = Micron): FY2027Q1 → 「約 2026 年 9–11 月」 (Micron's fiscal quarters end on the Thursday
 * closest to the end of Nov, Feb, May and Aug, so they can start or end a few days into the next month: FY2027Q1 runs
 * to early December 2026); FY2027 → 「約 2026 年 9 月至 2027 年 8 月」. With fyStart 2 (NVIDIA): FY2027Q1 →
 * 「約 2026 年 2–4 月」.
 */
export function calendarHint(p: string, fyStart = 9): string {
  const q = RE_Q.exec(p);
  if (q) {
    const y = Number(q[2]);
    const n = Number(q[3]);
    if (!q[1]) return `${y} 年 ${n * 3 - 2}–${n * 3} 月`;
    // month index from January of the year before the fiscal year's name
    const i0 = fyStart - 1 + (n - 1) * 3;
    const i1 = i0 + 2;
    const y0 = y - 1 + Math.floor(i0 / 12);
    const y1 = y - 1 + Math.floor(i1 / 12);
    const m0 = (i0 % 12) + 1;
    const m1 = (i1 % 12) + 1;
    return y0 === y1 ? `約 ${y0} 年 ${m0}–${m1} 月` : `約 ${y0} 年 ${m0} 月至 ${y1} 年 ${m1} 月`;
  }
  const yr = RE_Y.exec(p);
  if (yr?.[1]) {
    const y = Number(yr[2]);
    return fyStart === 1 ? `${y} 年 1–12 月` : `約 ${y - 1} 年 ${fyStart} 月至 ${y} 年 ${fyStart - 1} 月`;
  }
  return yr ? `${yr[2]} 年 1–12 月` : '';
}

/** Category key for MultiLine / bar charts: FY quarters become 「FY2026-Q4」 (grouped as FY26), others stay. */
export const chartKey = (p: string): string => p.replace(/^FY(\d{4})Q([1-4])$/, 'FY$1-Q$2');

/** Quarter ids from `from` to `to` inclusive. */
export function quarterRange(from: string, to: string): string[] {
  const out: string[] = [];
  let p = from;
  for (let i = 0; i < 200 && qIndex(p) <= qIndex(to); i++) {
    out.push(p);
    p = nextQuarter(p);
  }
  return out;
}

/** Calendar quarters overlapping a fiscal quarter (fyStart 9 = Micron: FY2027Q1 → 2026Q3, 2026Q4). */
export function calendarQuartersOf(p: string, fyStart = 9): string[] {
  const q = RE_Q.exec(p);
  if (!q) return [];
  if (!q[1]) return [p];
  const y = Number(q[2]);
  const n = Number(q[3]);
  const out: string[] = [];
  for (const i of [fyStart - 1 + (n - 1) * 3, fyStart - 1 + (n - 1) * 3 + 2]) {
    const id = `${y - 1 + Math.floor(i / 12)}Q${Math.floor((i % 12) / 3) + 1}`;
    if (!out.includes(id)) out.push(id);
  }
  return out;
}

// ───────────── numbers ─────────────

/** 「新台幣 861 億元」「603 億美元」 (amounts in millions; always in 億 so cards compare at a glance) */
export function fcMoney(millions: number | null | undefined, currency: string): string {
  if (millions == null || !Number.isFinite(millions)) return '—';
  return formatMoney(millions, currency, { unit: '億' });
}

/**
 * Number in 億 without the unit (tables with a unit header): 「861」「2,914」「6.1」. With explicit `digits` the
 * decimals are kept (「93.0」 next to 「98.5」), so a table column lines up.
 */
export function fcYi(millions: number | null | undefined, digits?: number): string {
  if (millions == null || !Number.isFinite(millions)) return '—';
  const v = scaleMillions(millions, '億');
  const d = digits ?? yiDigits(millions);
  return formatNumber(v, { digits: d, trim: digits == null });
}
/** Decimals fcYi uses for an amount in millions: 2 below 10 億, 1 below 100 億, else 0. */
export function yiDigits(millions: number): number {
  const v = Math.abs(scaleMillions(millions, '億'));
  return v < 10 ? 2 : v < 100 ? 1 : 0;
}

/** 「新台幣億元」「億美元」 */
export const fcYiUnit = (currency: string): string => moneyUnitLabel('億', currency);

/** 「65.1%」 (digits default 1) */
export function fcPct(v: number | null | undefined, digits = 1): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits })}%`;
}

/** Percent with the precision the source gives (guidance 86.25% stays 86.25%). */
export function fcPctExact(v: number | null | undefined): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits: 2, trim: true })}%`;
}

/** 「138.92 元」「37.30 美元」 */
export function fcEps(v: number | null | undefined, unit: string): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits: 2 })} ${unit}`;
}

/** Signed difference in percentage points: 「+2.5 個百分點」「−0.3 個百分點」 */
export function fcPp(v: number, digits = 1): string {
  return `${formatNumber(v, { digits, signed: true })} 個百分點`;
}

// ───────────── model helpers ─────────────

export type Candidate = ModelOutput['candidates'][number];
export type Scenario = ModelOutput['scenarios'][number];
export type ScenarioId = Scenario['id'];
export type Forecast = Scenario['forecasts'][number];
export type BacktestRow = ModelOutput['backtest'][number];
export type Quarter = CompanyInputs['quarters'][number];
export type Derived = ModelOutput['derived'][number];

export const SCENARIO_ORDER: readonly ScenarioId[] = ['bear', 'base', 'bull'];
/** Scenario colours, shared by the charts and the table headers (forecast.css uses the same tokens). */
export const SCENARIO_COLOR: Record<ScenarioId, string> = { bear: 'var(--chart-7)', base: 'var(--chart-2)', bull: 'var(--chart-3)' };

export const selectedCandidate = (m: ModelOutput): Candidate => m.candidates.find((c) => c.selected) ?? m.candidates[0]!;
export const scenarioOf = (m: ModelOutput, id: ScenarioId): Scenario | undefined => m.scenarios.find((s) => s.id === id);
export const forecastOf = (m: ModelOutput, id: ScenarioId, period: string): Forecast | undefined =>
  scenarioOf(m, id)?.forecasts.find((f) => f.period === period);
export const derivedOf = (m: ModelOutput, id: string): Derived | undefined => m.derived.find((d) => d.id === id);
export const paramOf = (m: ModelOutput, name: string) => m.parameters.find((p) => p.name === name);
export const paramStarting = (m: ModelOutput, prefix: string) => m.parameters.find((p) => p.name.startsWith(prefix));

/** Backtest rows of one candidate and metric, sorted by period. */
export function backtestOf(m: ModelOutput, candidate: string, metric: string): BacktestRow[] {
  return m.backtest.filter((b) => b.candidate === candidate && b.metric === metric).sort((a, b) => comparePeriods(a.period, b.period));
}

/** Forecast quarters (not years) of a scenario in order. */
export const forecastQuarters = (s: Scenario | undefined): Forecast[] => (s?.forecasts ?? []).filter((f) => isQuarter(f.period));

/** Quarter row of the inputs. */
export const quarterOf = (inp: CompanyInputs, p: string): Quarter | undefined => inp.quarters.find((q) => q.period === p);

/** The gross margin the model targets: gross profit ÷ revenue (群聯 TIFRS); non-GAAP when FC_META.nonGaap (美光). */
export function actualGrossMargin(c: FcCompany, q: Quarter): number | undefined {
  if (FC_META[c]?.nonGaap) return q.grossMarginNonGaap ?? (q.grossProfit != null ? (q.grossProfit / q.revenue) * 100 : undefined);
  return q.grossProfit != null ? (q.grossProfit / q.revenue) * 100 : undefined;
}
/** The EPS the model targets: the inputs' eps (群聯 basic); non-GAAP when FC_META.nonGaap (美光). */
export const actualEps = (c: FcCompany, q: Quarter): number | undefined => (FC_META[c]?.nonGaap ? (q.epsNonGaap ?? q.eps) : q.eps);

/** Quarters from `from` on (inclusive). */
export const quartersFrom = (inp: CompanyInputs, from: string): Quarter[] => inp.quarters.filter((q) => qIndex(q.period) >= qIndex(from));

/** Points of a market price series from a calendar quarter on. */
export function pricePoints(pr: MarketPrices, id: string, from?: string) {
  const s = pr.series.find((x) => x.id === id);
  if (!s) return { series: undefined, points: [] as MarketPrices['series'][number]['points'] };
  return { series: s, points: s.points.filter((p) => !from || !isQuarter(p.period) || qIndex(p.period) >= qIndex(from)) };
}

/** First calendar quarter of the price inputs plotted on a page (fiscal years: the one overlapping the first quarter). */
export function priceFrom(meta: FcMeta): string {
  return meta.fyStartMonth ? (calendarQuartersOf(meta.historyFrom, meta.fyStartMonth)[0] ?? meta.historyFrom) : meta.historyFrom;
}

/**
 * The company's own guidance for a forecast quarter, read from the model parameters (undefined when the model has
 * none, e.g. 群聯, 特斯拉). Convention for scripts/models/<id>.ts — parameter names start with the period:
 *   「FY2027Q1 財測：營收中值」 or 「2027Q1 營收財測中值」 (value in millions; the note gives the range as
 *   「± 3 億美元」, 「330–370 億美元」 or, for a percentage band such as 輝達's 「± 2%」, the percentage of the
 *   midpoint, and the source key in full-width parentheses 「（tr-q3-2026）」),
 *   「<period> 財測：毛利率…」／「<period> 財測：非 GAAP 毛利率」 (%), 「<period> 財測：EPS…」／「…非 GAAP EPS」.
 * The first forecast quarter with a revenue guidance wins. Without a source key in the note, the matching point of a
 * drivers series whose id contains 「guidance」 and 「revenue」 is cited.
 * Without such parameters the drivers' guidance series are read instead (guidancesFromDrivers): 台積電's
 * 「guidance-revenue-usd」 × 「fx-guidance」 (its US-dollar guidance at its own exchange-rate assumption, with `basis`
 * saying so) and 「guidance-gross-margin」.
 */
export interface NextGuidance {
  period: string;
  revenue: number;
  revenueLow?: number | undefined;
  revenueHigh?: number | undefined;
  grossMargin?: number | undefined;
  eps?: number | undefined;
  epsRange?: number | undefined;
  src?: string | undefined;
  /** how the page-currency figure was derived when the company guides in another currency (台積電) */
  basis?: string | undefined;
}

/** The guidance of a quarter from the drivers' guidance-revenue／guidance-gross-margin series (see nextGuidance). */
function guidanceFromDrivers(b: FcBundle, period: string): NextGuidance | undefined {
  const series = b.drivers?.series ?? [];
  const pointOf = (s: (typeof series)[number] | undefined) => s?.points.find((p) => p.period === period && p.status === 'guidance');
  const revS = series.find((s) => /^guidance-revenue(?:-usd)?$/.test(s.id) && pointOf(s));
  const rev = pointOf(revS);
  if (!revS || !rev || !/百萬/.test(revS.unit)) return undefined;
  const inUsd = /美元/.test(revS.unit);
  let k = 1;
  let basis: string | undefined;
  if (inUsd && b.meta.currency === 'TWD') {
    const fx = pointOf(series.find((s) => s.id === 'fx-guidance'));
    if (!fx) return undefined;
    k = fx.value;
    const yi = (v: number) => formatNumber(v / 100, { digits: 0 });
    const usd = rev.low != null && rev.high != null ? `${yi(rev.low)}–${yi(rev.high)}` : yi(rev.value);
    basis = `美元營收財測 ${usd} 億美元 × 公司的匯率假設 ${formatNumber(fx.value, { digits: 2, trim: true })}`;
  } else if (inUsd !== (b.meta.currency === 'USD')) return undefined;
  const gm = pointOf(series.find((s) => s.id === 'guidance-gross-margin'));
  return {
    period,
    revenue: rev.value * k,
    revenueLow: rev.low != null ? rev.low * k : undefined,
    revenueHigh: rev.high != null ? rev.high * k : undefined,
    grossMargin: gm?.value,
    src: b.sourceByKey.has(rev.src) ? rev.src : undefined,
    basis,
  };
}

export function nextGuidance(b: FcBundle): NextGuidance | undefined {
  const m = b.model;
  for (const f of forecastQuarters(scenarioOf(m, 'base'))) {
    const period = f.period;
    const named = (re: RegExp) =>
      m.parameters.find((p) => p.name.startsWith(`${period} `) && re.test(p.name.slice(period.length + 1)) && !/下緣|上緣/.test(p.name));
    const rev = named(/^(?:財測：營收|營收財測)/);
    if (!rev) {
      const d = guidanceFromDrivers(b, period);
      if (d) return d;
      continue;
    }
    const gm = named(/^財測：(?:非 GAAP )?毛利率/);
    const eps = named(/^財測：(?:非 GAAP )?EPS/);
    const note = rev.note ?? '';
    const pm = /±\s*([\d.]+)\s*億美?元/.exec(note);
    const rg = pm ? null : /([\d,]+(?:\.\d+)?)\s*[–-]\s*([\d,]+(?:\.\d+)?)\s*億美?元/.exec(note);
    // 「± 2%」 of the midpoint (輝達), only when the note gives no amount
    const pc = pm || rg ? null : /±\s*([\d.]+)\s*[%％]/.exec(note);
    const em = /±\s*([\d.]+)\s*美?元/.exec(eps?.note ?? '');
    const half = pm ? Number(pm[1]) * 100 : pc ? (rev.value * Number(pc[1])) / 100 : undefined;
    const lo = rg ? Number(rg[1]!.replace(/,/g, '')) * 100 : half != null ? rev.value - half : undefined;
    const hi = rg ? Number(rg[2]!.replace(/,/g, '')) * 100 : half != null ? rev.value + half : undefined;
    let src = /（([a-z0-9-]+)）/.exec(note)?.[1];
    if (!src || !b.sourceByKey.has(src))
      src = b.drivers?.series
        .filter((s) => /guidance/.test(s.id) && /revenue/.test(s.id))
        .flatMap((s) => s.points)
        .find((p) => p.period === period && p.status === 'guidance')?.src;
    return {
      period,
      revenue: rev.value,
      revenueLow: lo,
      revenueHigh: hi,
      grossMargin: gm?.value,
      eps: eps?.value,
      epsRange: em ? Number(em[1]) : undefined,
      src: src && b.sourceByKey.has(src) ? src : undefined,
    };
  }
  return undefined;
}

// ───────────── reported quarter, summary periods, forecast vs actual ─────────────

/** Latest reported quarter, where the forecasts start (群聯 2026Q3; falls back to the end of the backtest window). */
export const lastReportedOf = (m: ModelOutput): string => m.lastReported ?? m.test.to;

/** Monthly revenue rows that fall in a calendar quarter (群聯 2026Q4 → 2026-10…). */
export function monthsOfQuarter(inp: CompanyInputs, q: string): CompanyInputs['monthly'] {
  const m = RE_Q.exec(q);
  if (!m || m[1]) return [];
  const n = Number(m[3]);
  return inp.monthly.filter((x) => x.period.startsWith(`${m[2]}-`) && Math.ceil(Number(x.period.slice(5)) / 3) === n);
}

export interface SummaryPeriods {
  /** reported quarter shown first, with the site's earlier forecast for it (only when the model checks one) */
  actual: string | undefined;
  /** forecast periods: the first meta.summaryQuarters forecast quarters, then every full-year forecast */
  forecast: string[];
}
export function summaryPeriodsOf(b: FcBundle): SummaryPeriods {
  const base = scenarioOf(b.model, 'base');
  const qs = forecastQuarters(base)
    .slice(0, b.meta.summaryQuarters)
    .map((f) => f.period);
  const ys = (base?.forecasts ?? []).filter((f) => isYear(f.period)).map((f) => f.period);
  const live = b.model.liveChecks?.[0]?.period;
  return { actual: live && isQuarter(live) && quarterOf(b.inputs, live) ? live : undefined, forecast: [...qs, ...ys] };
}

/** Reported quarters inside a full year (2026 → 3 when 2026Q1–Q3 are reported). */
export const reportedQuartersIn = (inp: CompanyInputs, year: string): number =>
  inp.quarters.filter((q) => q.period.startsWith(year) && isQuarter(q.period)).length;

export type LiveCheck = NonNullable<ModelOutput['liveChecks']>[number];
export type PastForecast = CompanyInputs['pastForecasts'][number];
type LiveMetric = 'revenue' | 'grossMargin' | 'operatingIncome' | 'netIncome' | 'eps';
const LIVE_METRICS: readonly string[] = ['revenue', 'grossMargin', 'operatingIncome', 'netIncome', 'eps'];

export interface LiveRow extends LiveCheck {
  metric: LiveMetric;
  /** bear and bull values of the same release (inputs.pastForecasts) */
  low: number | undefined;
  high: number | undefined;
  /** where the actual sits against that bear–bull range; undefined when the field was already known (no range) */
  position: 'below' | 'inside' | 'above' | undefined;
  /** source of the past forecast (the site's page as published) */
  src: string | undefined;
}

/**
 * The model's forecast-vs-actual checks (model.liveChecks) with the bear–bull range of the same release from
 * inputs.pastForecasts, in metric order. Empty when the model has none (美光).
 */
export function liveRows(b: FcBundle): LiveRow[] {
  const pf = b.inputs.pastForecasts;
  return (b.model.liveChecks ?? [])
    .filter((c): c is LiveCheck & { metric: LiveMetric } => LIVE_METRICS.includes(c.metric))
    .map((c) => {
      const at = (id: ScenarioId) => pf.find((p) => p.madeOn === c.madeOn && p.period === c.period && p.scenario === id);
      const lo = at('bear')?.[c.metric];
      const hi = at('bull')?.[c.metric];
      const ranged = lo != null && hi != null && Math.abs(hi - lo) > 1e-9;
      const min = ranged ? Math.min(lo, hi) : undefined;
      const max = ranged ? Math.max(lo, hi) : undefined;
      const position = min == null || max == null ? undefined : c.actual < min ? 'below' : c.actual > max ? 'above' : 'inside';
      return { ...c, low: min, high: max, position, src: at(c.scenario)?.src } as LiveRow;
    })
    .sort((x, y) => LIVE_METRICS.indexOf(x.metric) - LIVE_METRICS.indexOf(y.metric));
}

/**
 * Whether the gross-margin and expense errors of the checked quarter offset each other (群聯 2026Q3): the margin was
 * overestimated by more than 1 point, the operating-income error is well under the gross-profit error that the margin
 * miss implies on the known revenue, and EPS came out within 3%. The page then says plainly that the close EPS does
 * not mean the margin was right (hero line and 「為什麼毛利率高估，EPS 卻很接近」).
 */
export function liveOffset(b: FcBundle, rows: LiveRow[] = liveRows(b)): boolean {
  const by = (t: LiveMetric) => rows.find((r) => r.metric === t);
  const gm = by('grossMargin');
  const oi = by('operatingIncome');
  const eps = by('eps');
  const period = rows[0]?.period;
  const revenue = by('revenue')?.actual ?? (period ? quarterOf(b.inputs, period)?.revenue : undefined);
  if (!gm || !oi || !eps || gm.errorPp == null || eps.errorPct == null || revenue == null) return false;
  const gpErr = (revenue * gm.errorPp) / 100;
  const oiErr = oi.forecast - oi.actual;
  return gm.errorPp > 1 && oiErr < gpErr * 0.6 && Math.abs(eps.errorPct) < 3;
}

/** 「高估」「低估」「幾乎沒有誤差」 for a signed error (forecast − actual). */
export const overUnderOf = (e: number): string => (Math.abs(e) < 0.05 ? '幾乎沒有誤差' : e > 0 ? '高估' : '低估');

/** The results event of a reported quarter: 「2026 年第三季營收 860.76 億元、毛利率 59.7%」 (date and source). */
export function resultsEventOf(b: FcBundle, q: string) {
  const head = periodLabel(q, 'long');
  return b.inputs.events.find((e) => e.title.startsWith(head) && !/法說會訂於/.test(e.title));
}

/** 「2025 年至 2026 年上半年」「FY2025–FY2026」「2025 年第三季至 2026 年第二季」 */
export function spanLabel(from: string, to: string): string {
  const a = RE_Q.exec(from);
  const z = RE_Q.exec(to);
  if (!a || !z) return `${periodLabel(from)}–${periodLabel(to)}`;
  if (a[1] || z[1]) return a[3] === '1' && z[3] === '4' ? `FY${a[2]}–FY${z[2]}` : `${periodLabel(from)}–${periodLabel(to)}`;
  const start = a[3] === '1' ? `${a[2]} 年` : periodLabel(from, 'long');
  const end = z[3] === '4' ? `${z[2]} 年` : z[3] === '2' ? `${z[2]} 年上半年` : periodLabel(to, 'long');
  return `${start}至 ${end}`;
}

/** Meta description of a model page, following the data (backtest window, checked quarter, forecast periods). */
export function fcDescription(b: FcBundle): string {
  const m = b.model;
  const { actual, forecast } = summaryPeriodsOf(b);
  const years = forecast.filter(isYear);
  if (b.meta.topic === 'forecast') {
    const n = qIndex(m.test.to) - qIndex(m.test.from) + 1;
    const guided = m.candidates.some((c) => c.id === 'guidance') || !!nextGuidance(b);
    return `${b.meta.descLead ?? `拆解${b.meta.name}的營收與毛利率`}，回測 ${spanLabel(m.test.from, m.test.to)}共 ${n} 季${guided ? `並對照${b.meta.name}自己的財測` : ''}，再以保守、基準、樂觀三種情境推估 ${joinZh(forecast.map((p) => periodLabel(p, 'long')), '與')}。模型推估，不是投資建議。`;
  }
  if (b.company === 'micron') {
    const n = qIndex(m.test.to) - qIndex(m.test.from) + 1;
    return `以 TrendForce 合約價、位元出貨與每位元成本拆解美光的營收與毛利率，回測 ${spanLabel(m.test.from, m.test.to)} 共 ${n} 季並對照美光自己的財測，再以三種情境推估 ${joinZh(years.map((y) => periodLabel(y)), '與')} 各季與全年。模型推估，不是投資建議。`;
  }
  return `用 TrendForce NAND 合約價推估群聯的進貨成本，對照庫存何時賣出，回測 ${spanLabel(m.test.from, m.test.to)}的毛利率與 EPS${actual ? `、檢驗本站對 ${periodLabel(actual, 'long')}的預測` : ''}，並以保守、基準、樂觀三種情境推估 ${joinZh(forecast.map((p) => periodLabel(p, 'long')), '與')}。模型推估，不是投資建議。`;
}

// ───────────── citations in model text ─────────────

export type CitePart = string | { cite: string };

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\-]/g, '\\$&');
const reCache = new WeakMap<FcBundle, RegExp>();
function keyRe(b: FcBundle): RegExp {
  let re = reCache.get(b);
  if (!re) {
    const keys = [...b.sourceByKey.keys()].sort((x, y) => y.length - x.length).map(escapeRe);
    // not inside a marker that is already there (「⟦src:key⟧」 from a quarter range)
    re = new RegExp(`(?<![A-Za-z0-9:-])(${keys.join('|')})(?![A-Za-z0-9⟧-])`, 'g');
    reCache.set(b, re);
  }
  return re;
}

/**
 * Page conventions applied to the model's generated text (which keeps the raw units of the inputs): amounts in
 * 「百萬元」「百萬美元」 become 億 like the rest of the page (docs/STYLE-zh-TW.md: large numbers in 萬／億／兆), e.g.
 * 「86,076 百萬元」 → 「860.8 億元」; a hyphen-minus before a number becomes 「−」 (「誤差 -1.3%」 → 「誤差 −1.3%」).
 * Source keys (「tf-20260930-13258」) and dates are left alone: the minus rule needs a non-word character before it.
 */
export function fcPageText(text: string): string {
  return text
    .replace(/(\d[\d,]*(?:\.\d+)?)\s*百萬(美)?元/g, (_m, n: string, usd: string | undefined) => {
      const v = Number(n.replace(/,/g, '')) / 100;
      return `${formatNumber(v, { digits: v >= 1000 ? 0 : 1, trim: true })} 億${usd ? '美' : ''}元`;
    })
    .replace(/(^|[\s（(，、：；=＝])-(?=\d)/g, '$1−');
}

/**
 * Split model text into plain strings and citation markers: a raw source key such as 「（rm-fy2026q4）」 becomes [n];
 * a quarter range 「rm-fy2026q1–q4」 cites each quarter. Plain strings follow the page conventions (fcPageText).
 */
export function citeParts(b: FcBundle, text: string | null | undefined): CitePart[] {
  if (!text) return [];
  const has = (k: string) => b.sourceByKey.has(k);
  let t = text.replace(/\b((?:rm|pr|f|sec)-fy\d{4})q([1-4])–q([1-4])\b/g, (m, base: string, a: string, z: string) => {
    const ks: string[] = [];
    for (let i = Number(a); i <= Number(z); i++) if (has(`${base}q${i}`)) ks.push(`${base}q${i}`);
    return ks.length ? ks.map((k) => `⟦src:${k}⟧`).join('') : m;
  });
  t = t.replace(keyRe(b), (_m, k: string) => `⟦src:${k}⟧`);
  // 「（⟦a⟧、⟦b⟧）」 → markers only; 「…，⟦a⟧）」 → 「…⟦a⟧）」
  t = t.replace(/[（(]\s*((?:⟦src:[^⟧]+⟧[\s、，,]*)+)[）)]/g, (_m, inner: string) => inner.replace(/[\s、，,]+/g, ''));
  t = t.replace(/[，、]\s*((?:⟦src:[^⟧]+⟧)+)\s*(?=[）)])/g, '$1');
  const out: CitePart[] = [];
  let last = 0;
  for (const m of t.matchAll(/⟦src:([^⟧]+)⟧/g)) {
    if (m.index! > last) out.push(fcPageText(t.slice(last, m.index)));
    out.push({ cite: m[1]! });
    last = m.index! + m[0].length;
  }
  if (last < t.length) out.push(fcPageText(t.slice(last)));
  return out;
}

/** Keys cited inside a text (see citeParts). */
export const citesIn = (b: FcBundle, text: string | null | undefined): string[] =>
  citeParts(b, text).flatMap((p) => (typeof p === 'string' ? [] : [p.cite]));

/** Plain text with the citation markers removed (aria labels, chart notes). */
export const plainText = (b: FcBundle, text: string | null | undefined): string =>
  citeParts(b, text)
    .map((p) => (typeof p === 'string' ? p : ''))
    .join('')
    .replace(/（\s*）/g, '');

// ───────────── page sources ─────────────

/** Keys of the price-series points a page plots (its series, from priceFrom()). */
export function priceKeys(b: FcBundle): string[] {
  const from = priceFrom(b.meta);
  return b.meta.priceSeries.flatMap((id) => pricePoints(b.prices, id, from).points.map((p) => p.src));
}

// ───────────── drivers ─────────────

export type DriverSeries = CompanyDrivers['series'][number];
export type DriverPoint = DriverSeries['points'][number];

/**
 * Whether a driver point falls in the page's window (FC_META.historyFrom on): quarters from that quarter, months and
 * years from its year (a fiscal year 「FY2020」 counts as 2020). Points before it are not in the page's source list.
 * On a fiscal-year page (fyStartMonth with historyFrom 「FY2020Q1」) calendar points start where that fiscal quarter
 * starts, because qIndex puts FY2020Q1 at 2020Q1: for 輝達 (fyStartMonth 2) the window opens at 2019Q1, 2019-02 and
 * 2019, not a year later; fiscal points (「FY2021Q3」「FY2021」) still compare with historyFrom.
 */
export function inWindow(meta: FcMeta, period: string): boolean {
  const fq = meta.fyStartMonth ? RE_Q.exec(meta.historyFrom) : null;
  const fiscalPage = !!fq?.[1];
  const fiscalPoint = period.startsWith('FY');
  if (isQuarter(period)) return qIndex(period) >= qIndex(fiscalPage && !fiscalPoint ? priceFrom(meta) : meta.historyFrom);
  const y = Number(/^(?:FY)?(\d{4})/.exec(period)?.[1] ?? Number.NaN);
  if (!Number.isFinite(y)) return true;
  if (fiscalPage && !fiscalPoint) {
    // first calendar month of historyFrom: FY2020Q1 with fyStartMonth 2 → 2019-02
    const i0 = Number(meta.fyStartMonth) - 1 + (Number(fq![3]) - 1) * 3;
    const y0 = Number(fq![2]) - 1 + Math.floor(i0 / 12);
    const m0 = (i0 % 12) + 1;
    const mo = /^\d{4}-(\d{2})$/.exec(period);
    return mo ? y * 12 + Number(mo[1]) >= y0 * 12 + m0 : y >= y0;
  }
  const y0 = Number(/^(?:FY)?(\d{4})/.exec(meta.historyFrom)?.[1] ?? 0);
  return y >= y0;
}

/** Driver series with their points inside the page window, grouped by category in file order (empty groups dropped). */
export function driverGroups(b: FcBundle): Array<{ category: string; series: Array<DriverSeries & { shown: DriverPoint[] }> }> {
  const out: Array<{ category: string; series: Array<DriverSeries & { shown: DriverPoint[] }> }> = [];
  for (const s of b.drivers?.series ?? []) {
    const shown = s.points.filter((p) => inWindow(b.meta, p.period));
    if (!shown.length) continue;
    let g = out.find((x) => x.category === s.category);
    if (!g) out.push((g = { category: s.category, series: [] }));
    g.series.push({ ...s, shown });
  }
  return out;
}

/** A driver series by id. */
export const driverOf = (b: FcBundle, id: string): DriverSeries | undefined => b.drivers?.series.find((s) => s.id === id);

/** Sources of every driver point inside the page window (the generic driver tables and company sections cite them). */
export function driverKeys(b: FcBundle): string[] {
  return [...new Set(driverGroups(b).flatMap((g) => g.series.flatMap((s) => s.shown.map((p) => p.src))))];
}

/**
 * Every source a page cites, in list order (company sources first, then market prices). The components cite only
 * keys collected here: the model's sourceKeys and keys named in its text, scenario assumptions, events, annual
 * reports, monthly revenue, the quarters and guidance shown from meta.historyFrom on, and the plotted price points.
 */
export function pageSourceKeys(b: FcBundle, extra: readonly string[] = []): string[] {
  const { model: m, inputs } = b;
  const used = new Set<string>(m.sourceKeys);
  const addText = (s: string | undefined) => {
    for (const k of citesIn(b, s)) used.add(k);
  };
  addText(m.summary);
  addText(m.liveCheckSummary);
  for (const c of m.liveChecks ?? []) addText(c.note);
  for (const p of inputs.pastForecasts) used.add(p.src);
  for (const c of m.candidates) {
    addText(c.description);
    addText(c.note);
    c.equations.forEach(addText);
  }
  for (const p of m.parameters) addText(p.note);
  for (const d of m.derived) addText(d.note);
  for (const s of m.scenarios) {
    for (const a of s.assumptions) {
      if (a.src) used.add(a.src);
      addText(a.value);
    }
    for (const f of s.forecasts) addText(f.note);
  }
  for (const s of m.sensitivities) addText(s.effect);
  m.limitations.forEach(addText);
  for (const e of inputs.events) used.add(e.src);
  // /forecast/ pages cite the keys written inside event details and driver definitions (EventTimeline, DriverTables)
  if (b.meta.topic === 'forecast') {
    for (const e of inputs.events) addText(e.detail);
    for (const s of b.drivers?.series ?? []) {
      addText(s.definition);
      addText(s.note);
    }
  }
  for (const a of inputs.annual) used.add(a.src);
  for (const mo of inputs.monthly) used.add(mo.src);
  for (const q of quartersFrom(inputs, b.meta.historyFrom)) {
    used.add(q.src);
    if (q.guidance) used.add(q.guidance.src);
  }
  for (const k of priceKeys(b)) used.add(k);
  const g = nextGuidance(b);
  if (g?.src) used.add(g.src);
  for (const k of driverKeys(b)) used.add(k);
  for (const k of extra) used.add(k);
  const order = [...new Set([...Object.keys(inputs.sources), ...Object.keys(b.drivers?.sources ?? {}), ...Object.keys(b.prices.sources)])];
  for (const k of used) if (!b.sourceByKey.has(k)) console.warn(`[forecast-data] ${b.company}: cited key "${k}" has no source`);
  return order.filter((k) => used.has(k));
}

/** The page's source list (see pageSourceKeys; `extra` = keys a company section cites beyond the defaults). */
export function pageSources(b: FcBundle, extra: readonly string[] = []): SourceT[] {
  return pageSourceKeys(b, extra).map((k) => b.sourceByKey.get(k)!);
}
